import React from "react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  HomeIcon,
  UsersIcon,
  WalletIcon,
  MegaphoneIcon,
  ArrowRightOnRectangleIcon,
  CheckCircleIcon,
  ChatBubbleLeftIcon,
} from "@heroicons/react/24/outline";

export default function AdminSidebar() {
  const navigate = useNavigate();
  const location = useLocation();

  const sidebarItems = [
    { name: "Dashboard", icon: <HomeIcon className="w-5 h-5" />, path: "/admin-dashboard" },
    { name: "User Reports", icon: <UsersIcon className="w-5 h-5" />, path: "/user-reports" },
    { name: "Account Verification", icon: <CheckCircleIcon className="w-5 h-5" />, path: "/account-verification" },
    { name: "Wallet Requests", icon: <WalletIcon className="w-5 h-5" />, path: "/wallet-logs" },
    { name: "User Messages", icon: <ChatBubbleLeftIcon className="w-5 h-5" />, path: "/admin-messages" },
    { name: "Post Announcement", icon: <MegaphoneIcon className="w-5 h-5" />, path: "/announcements" },
  ];

  const isActive = (path) => location.pathname === path;

  return (
    <div className="w-72 bg-white shadow-xl z-20 flex flex-col h-screen">
      {/* Logo Section */}
      <div className="p-6 bg-gradient-to-r from-blue-600 to-indigo-600">
        <h1 className="text-xl font-bold text-white">Admin Dashboard</h1>
        <p className="text-blue-100 text-sm mt-1">System Management</p>
      </div>

      {/* Navigation */}
      <nav className="p-4 space-y-2 flex-1 overflow-y-auto">
        {sidebarItems.map((item) => (
          <button
            key={item.name}
            onClick={() => navigate(item.path)}
            className={`flex items-center w-full p-3 rounded-xl transition-all duration-200 group ${
              isActive(item.path)
                ? "bg-gradient-to-r from-blue-100 to-indigo-100 text-blue-600"
                : "text-gray-600 hover:text-blue-600 hover:bg-gradient-to-r from-blue-50 to-indigo-50"
            }`}
          >
            <div className={`p-2 rounded-lg shadow-sm group-hover:scale-110 transition-transform duration-200 ${
              isActive(item.path) ? "bg-blue-200" : "bg-white"
            }`}>
              {item.icon}
            </div>
            <span className="ml-3 font-medium">{item.name}</span>
          </button>
        ))}
      </nav>

      {/* Logout Section */}
      <div className="p-4 border-t">
        <button
          onClick={() => {
            localStorage.removeItem("token");
            localStorage.removeItem("user");
            navigate("/");
          }}
          className="flex items-center w-full p-3 text-red-600 hover:bg-red-50 rounded-xl transition-all duration-200 group"
        >
          <div className="bg-white p-2 rounded-lg shadow-sm group-hover:scale-110 transition-transform duration-200">
            <ArrowRightOnRectangleIcon className="w-5 h-5" />
          </div>
          <span className="ml-3 font-medium">Log Out</span>
        </button>
      </div>
    </div>
  );
}
